mapper.select:
SELECT * FROM RPT_FREE_REPORT_BATCH


        AND (REPORT_NAME LIKE CONCAT('%', #{keyword}, '%')
             OR FILE_NAME LIKE CONCAT('%', #{keyword}, '%'))

    AND IMPORT_TIME >= #{dateFrom}
    AND IMPORT_TIME < #{dateTo}

ORDER BY IMPORT_TIME DESC LIMIT 200

SELECT b.* FROM RPT_FREE_REPORT_BATCH b

    INNER JOIN EXT_USER_ORG uo ON b.UPLOADER_EMP_ID = uo.USER_ID



        AND (b.REPORT_NAME LIKE CONCAT('%', #{keyword}, '%')
             OR b.FILE_NAME LIKE CONCAT('%', #{keyword}, '%'))

    AND b.IMPORT_TIME >= #{dateFrom}
    AND b.IMPORT_TIME < #{dateTo}
    AND b.UPLOADER_EMP_ID = #{scopeEmpId}

        AND uo.ORG_CODE IN
        #{code}


ORDER BY b.IMPORT_TIME DESC LIMIT 200
